```jsx
emailjs.sendForm(SERVICE_ID, TEMPLATE_ID, form.current, PUBLIC_KEY)
  .then(() => {
    setStatus('success')  // Runs even if unmounted!
    form.current.reset()
  }, () => {
    setStatus('error')    // Runs even if unmounted!
  })
```

**Issue**: If the user navigates away while the email is sending, `setStatus()` fires on an unmounted component. While React 18+ doesn't warn about this in production, it's wasteful and can cause issues with form references.

**Fix**: Track mount state:

```jsx
const mountedRef = useRef(true)
useEffect(() => () => { mountedRef.current = false }, [])

emailjs.sendForm(SERVICE_ID, TEMPLATE_ID, form.current, PUBLIC_KEY)
  .then(() => {
    if (!mountedRef.current) return
    setStatus('success')
    form.current?.reset()
  }, () => {
    if (mountedRef.current) setStatus('error')
  })
```

**Issue**: The typewriter uses `setTimeout` with delays of 30-70ms. Each call creates a new closure capturing all state, and the `useEffect` cleanup cancels the timer. This creates and destroys ~20 timers/second during typing. The effect also depends on `text` which changes every 30-70ms, causing the entire effect body to re-evaluate.

**Fix**: This is acceptable for a typewriter, but could be optimized with `useRef` for the progress and `requestAnimationFrame`:

```jsx
function Typewriter({ className }) {
  const [displayText, setDisplayText] = useState('')
  const progressRef = useRef({ idx: 0, len: 0, deleting: false })

  useEffect(() => {
    let rafId, lastTick = 0
    const tick = (time) => {
      if (time - lastTick < (progressRef.current.deleting ? 30 : 70)) {
        rafId = requestAnimationFrame(tick)
        return
      }
      lastTick = time
      const p = progressRef.current
      const phrase = PHRASES[p.idx]

      if (!p.deleting && p.len === phrase.length) {
        setTimeout(() => { p.deleting = true }, 2200)
        rafId = requestAnimationFrame(tick)
        return
      }
      if (p.deleting && p.len === 0) {
        setTimeout(() => {
          p.deleting = false
          p.idx = (p.idx + 1) % PHRASES.length
        }, 300)
        rafId = requestAnimationFrame(tick)
        return
      }

      p.len += p.deleting ? -1 : 1
      setDisplayText(phrase.substring(0, p.len))
      rafId = requestAnimationFrame(tick)
    }
    rafId = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafId)
  }, [])

  return <span className={className}>{displayText}<span className="cursor" /></span>
}
```

